def gen(rng):
    def wrap(s):
        if s.isdigit() or s == 'x':
            return s
        return '(' + s + ')'

    def lit(big):
        if big:
            return str(rng.choice([rng.randint(0, 9), rng.randint(0, 1000), rng.randint(0, 10**9)]))
        return str(rng.randint(0, 12))

    def build(k, withx, big):
        if k == 1:
            return 'x' if withx else lit(big)
        op = rng.choice('+-*')
        k1 = rng.randint(1, k - 1)
        k2 = k - k1
        if op == '*':
            if withx:
                if rng.random() < 0.5:
                    return wrap(build(k1, True, big)) + '*' + wrap(build(k2, False, big))
                return wrap(build(k1, False, big)) + '*' + wrap(build(k2, True, big))
            return wrap(build(k1, False, big)) + '*' + wrap(build(k2, False, big))
        if withx:
            x1, x2 = rng.choice([(True, False), (False, True), (True, True)])
        else:
            x1, x2 = False, False
        l = build(k1, x1, big)
        r = build(k2, x2, big)
        if rng.random() < 0.3:
            l = wrap(l)
        if rng.random() < 0.3:
            r = wrap(r)
        return l + op + r

    def value(expr, x0, M):
        vals = []
        ops = []
        prec = {'+': 1, '-': 1, '*': 2}

        def apply():
            o = ops.pop()
            b = vals.pop()
            a = vals.pop()
            if o == '+':
                vals.append((a + b) % M)
            elif o == '-':
                vals.append((a - b) % M)
            else:
                vals.append((a * b) % M)

        i = 0
        L = len(expr)
        while i < L:
            c = expr[i]
            if c.isdigit():
                j = i
                while j < L and expr[j].isdigit():
                    j += 1
                vals.append(int(expr[i:j]) % M)
                i = j
                continue
            if c == 'x':
                vals.append(x0 % M)
            elif c == '(':
                ops.append(c)
            elif c == ')':
                while ops[-1] != '(':
                    apply()
                ops.pop()
            else:
                while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[c]:
                    apply()
                ops.append(c)
            i += 1
        while ops:
            apply()
        return vals[0] % M

    def fmt(expr, M, x0=None):
        if x0 is None:
            x0 = rng.randint(0, M - 1)
        P = value(expr, x0, M)
        return expr + '\n' + str(P) + ' ' + str(M)

    def chain(limit, M):
        parts = []
        total = 0
        has_x = False
        while True:
            k = rng.randint(1, 8)
            wx = rng.random() < 0.6 or not has_x
            t = build(k, wx, True)
            if rng.random() < 0.5:
                t = wrap(t)
            piece = ('' if not parts else rng.choice('+-')) + t
            if total + len(piece) > limit:
                break
            parts.append(piece)
            total += len(piece)
            has_x = has_x or ('x' in t)
        return ''.join(parts)

    tests = [
        '4+x+2\n8 9',
        '2*(x+(x+3)*9)\n2 6',
        '(x-5)*3-x\n1 10',
        'x\n0 1',
        'x\n5 10',
        '7\n2 5',
        '7*x\n0 1',
        'x-x+3\n3 4',
        '5*x\n5 6',
        '2*x\n4 6',
        'x*1000000000\n0 1000000',
        'x+1000000000\n0 1000000',
        '(x)\n0 7',
    ]
    for _ in range(8):
        M = rng.randint(1, 6)
        tests.append(fmt(build(rng.randint(2, 6), True, False), M))
    for _ in range(20):
        M = rng.choice([rng.randint(1, 30), rng.randint(1, 30), rng.randint(30, 5000)])
        tests.append(fmt(build(rng.randint(2, 14), True, False), M))
    for _ in range(8):
        M = rng.choice([2, 4, 6, 8, 12, 16, 100, 1000])
        tests.append(fmt(build(rng.randint(3, 10), True, True), M))
    # deep nesting (depth <= 5000)
    D = 4000
    tests.append(fmt('x+(' * D + '1' + ')' * D, 999983, 999982))
    D = 3000
    tests.append(fmt('3*(x+' * D + '1' + ')' * D, 1000000, 999999))
    s = 'x'
    for i in range(3000):
        s = '(' + s + '+' + str(i % 10) + ')'
    tests.append(fmt(s, 999983, 999000))
    # max-size expressions
    for M, x0 in ((999983, 999982), (1000000, 999999), (999979, 987654), (1000000, 524288)):
        tests.append(fmt(chain(100000, M), M, x0))
    return tests
